"""Compile durable human-reviewed source notes, lesson ranges, and task taxonomy."""
from pathlib import Path
import json,csv,collections
ROOT=Path(__file__).resolve().parents[1];target=ROOT/'references/propisi-2019-content.json';data=json.loads(target.read_text())
with (ROOT/'references/propisi-2019-content/pages-review.tsv').open() as f:rows=list(csv.DictReader(f,delimiter='\t'))
assert [int(r['pdf_page']) for r in rows]==list(range(1,73))
pages=[]
for r in rows:
 n=int(r.pop('pdf_page'));features=r.pop('features').split(',');pages.append({'pdf_page':n,'printed_page':n if 3<=n<=71 else None,**r,'features':features,'review':'full-page visual review; task details checked from page image','preview':f'propisi-2019-content/pages/page-{n:02d}.jpg'})
order=json.loads((ROOT/'references/propisi-2019-order.json').read_text());groups=[]
for i,letter in enumerate(order['order']):
 start=order['firstLessonPages'][letter];end=order['firstLessonPages'][order['order'][i+1]]-1 if i+1<len(order['order']) else 70
 group=pages[start-1:end]
 groups.append({'letter':letter,'ordinal':i+1,'start':start,'end':end,'count':end-start+1,'range':str(start) if start==end else f'{start}-{end}','structure':' → '.join(p['kind'] for p in group),'page_ids':list(range(start,end+1)),'features':sorted(set(f for p in group for f in p['features']))})
assert len(groups)==33 and [p for g in groups for p in g['page_ids']]==list(range(8,71))
data.update({'status':'complete','reviewed_on':'2026-11-03','method':'Полные изображения всех 72 страниц просмотрены визуально в листах по шесть страниц; К 17-18 и существенные текстовые/смысловые задания проверены отдельно в полном размере. OCR всего файла не выполнялся. Описания являются пересказом; неоднозначные мелкие слова не транскрибированы.','pages':pages,'lesson_groups':groups,'group_size_counts':dict(collections.Counter(g['count'] for g in groups)),'legend':[{'code':code,'meaning':text} for code,text in [('change','измени по образцу'),('stress','поставь ударение'),('syllables','слово раздели на слоги'),('vowels','подчеркни гласные'),('soft-consonants','подчеркни мягкие согласные'),('question','ответь на вопрос'),('remember','запомни'),('missing-letter','вставь букву'),('missing-word','вставь слово'),('word-family','выдели в слове общую часть'),('copy','спиши'),('practice','задания для тренировки'),('lesson-end','окончание урока'),('copy-primer','спиши из букваря')]],'findings':[
 ['Главная поправка','Уроки не построены по одному шаблону. Из 33 буквенных групп 9 занимают одну страницу, 18 - две, 6 - три. Заголовок новой буквы не описывает содержание следующих страниц.'],
 ['Уже Т - три страницы','Т - 7-я буквенная группа, страницы 14-16. К - 8-я, страницы 17-18. С - 9-я, страницы 19-20. Здесь уже есть целые предложения, пропуски, изменение по образцу и повторение.'],
 ['Дальше растёт самостоятельность','Тексты для списывания: пустыня (28), Жучка (49), котёнок (52), Земля (42). Есть ответ на вопрос (35), сборка предложения из слов (46), загадка (68), итоговый текст с пропусками (71). Это разные письменные действия.'],
 ['Что это проверяет','Обводка учит форме, списывание - воспроизведению текста, дополнение и ответ - выбору содержания. Наличие этих заданий не означает, что пособие задаёт автоматические баллы, уровни допуска или обязательное число успешных попыток.'],
 ['Как адаптировать под наш ГОСТ','Сохранять рост сложности и буквенные группы, но использовать точные ГОСТ-формы и релевантные части. Короткое занятие - часть урока, а не универсальное сокращение всего материала буквы до одинакового набора полей.'],
 ['Что не переносить автоматически','Школьные связки, наклонная сетка, требование неотрывного движения и вся грамматическая программа не становятся задачами нашего тренажёра по факту наличия в источнике. Содержание и объём каждой группы требуют авторской адаптации.']
 ],'adaptation':{'status':'reference only; app build 27 not changed by this review','preserve':['ГОСТ типа Б без наклона; геометрическая проверка без порядка штрихов и требования неотрывности','Одна страница приложения на букву: внутри могут быть несколько последовательных блоков/занятий','Уже введённые буквы в тексте, понятный образец и постепенное уменьшение помощи','Ручные составы и все чернила сохраняются при будущей адаптации'],'proposed_progression':[{'stage':'знакомство','writing':'части ГОСТ и формы буквы, короткие сочетания','source_pages':[8,13,14]},{'stage':'применение','writing':'несколько слов, предложения, связь текста и смысла','source_pages':[17,18,19,20]},{'stage':'связное письмо','writing':'копирование короткого текста на доступном буквенном составе','source_pages':[28,31,42,49,52]},{'stage':'дополнение и самостоятельный ответ','writing':'пропуски, сборка фразы или короткий ответ с отдельным местом для письма','source_pages':[24,35,46,68,71]}],'not_decided':['Обязательный объём и деление на короткие занятия для каждой буквы','Какие языковые упражнения полезны именно обучению ГОСТ, а какие исключить','Способ ввода свободного ответа и его проверки; не заменять его заранее выбранным словом без отдельного решения']} })
for p in pages:p['letter_group']=next((g['letter'] for g in groups if g['start']<=p['pdf_page']<=g['end']),None)
target.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'pages':len(pages),'groups':len(groups),'sizes':data['group_size_counts'],'json_bytes':target.stat().st_size},ensure_ascii=False))
